  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Omarchy homepage submission by Palash Deb",
  "engines": {
    "node": ">=22.12.0"
  },
  "scripts": {
    "search:index": "node scripts/build-search-index.mjs",
    "predev": "npm run search:index",
    "dev": "vite",
    "prebuild": "npm run search:index",
    "build": "vite build",
    "check": "tsc --noEmit",
    "deploy": "npm run build && wrangler deploy"
  },
  "dependencies": {
    "@fontsource-variable/jetbrains-mono": "^5.3.0",
    "@orama/orama": "^3.1.18",
    "@solidjs/web": "2.0.0-rc.4",
    "@stylexjs/stylex": "^0.19.0",
