export type SiteSearchDocument = {
  id: string;
  title: string;
  url: string;
  section: string;
  kind: string;
  content: string;
  icon: string;
};

const schema = {
  id: 'string',
  title: 'string',
  url: 'string',
  section: 'string',
  kind: 'string',
  content: 'string',
  icon: 'string',
} as const;

async function createSiteSearch() {
  const [{ create, insertMultiple, search }, response] = await Promise.all([
    import('@orama/orama'),
    fetch('/site-search-index.json'),
  ]);
  if (!response.ok) throw new Error(`Search index request failed with ${response.status}`);

  const documents = await response.json() as SiteSearchDocument[];
  const database = create({ schema });
  await insertMultiple(database, documents, 200);
  return { database, search };
}

let databasePromise: ReturnType<typeof createSiteSearch> | undefined;

export function preloadSiteSearch() {
  databasePromise ??= createSiteSearch().catch((error) => {
    databasePromise = undefined;
    throw error;
  });
  return databasePromise;
}

export async function searchSite(term: string, limit = 10) {
  const engine = await preloadSiteSearch();
  const result = await engine.search(engine.database, {
    term,
    properties: ['title', 'section', 'content'],
    boost: { title: 3, section: 1.5 },
    tolerance: term.length >= 5 ? 1 : 0,
    limit,
  });

  return result.hits.map((hit) => hit.document as SiteSearchDocument);
}

export async function relatedSiteDocuments(document: SiteSearchDocument, excludeIds: string[] = [], limit = 7) {
  const excluded = new Set([document.id, ...excludeIds]);
  const collect = (documents: SiteSearchDocument[], current: SiteSearchDocument[]) => {
    for (const candidate of documents) {
      if (excluded.has(candidate.id) || current.some((item) => item.id === candidate.id)) continue;
      current.push(candidate);
      if (current.length === limit) break;
    }
    return current;
  };

  const related = collect(await searchSite(document.section, limit * 6), []);
  if (related.length < limit && document.section !== document.title) {
    collect(await searchSite(document.title, limit * 4), related);
  }

  return related;
}

// Client-side search over the manual. The index is built by bin/build-manual —
// one entry per heading — and fetched the first time someone reaches for the box.

const INDEX_URL = '/manual/search-index.json';
const MAX_RESULTS = 8;
const PREVIEW_LENGTH = 160;

let entries = null;
let loading = null;

function ready() {

  var search = document.querySelector('.search');

  if(search) {

    var input = search.querySelector('.search__input');
    var results = search.querySelector('.search__results');

    var query = '';
    var matches = [];
    var active = -1;

    search.hidden = false;

    input.addEventListener('focus', () => { load(); });
    input.addEventListener('input', () => { run(input.value); });
    input.addEventListener('keydown', (e) => { navigate(e); });

    results.addEventListener('mousedown', (e) => {

      // Hold the focus so the blur doesn't close the results before the click lands.
      // The link still navigates itself, so middle and modifier clicks keep working.
      if(e.target.closest('.search__result')) e.preventDefault();

    });

    search.addEventListener('focusout', (e) => {

      if(!search.contains(e.relatedTarget)) close();

    });

    document.addEventListener('keydown', (e) => {

      // A chapter hides the box at narrow widths, where there's nothing to focus
      if(shortcut(e) && input.offsetParent) {

        e.preventDefault();

        input.focus();
        input.select();

      }

    });

    function run(value) {

      query = value.trim();

      if(!query) return close();

      if(!entries) return load().then(resume);

      matches = lookup(entries, query).slice(0, MAX_RESULTS);
      active = -1;

      render();

    }

    // The index finished loading — or failed to — while the query was being typed
    function resume() {

      if(query != input.value.trim()) return;

      entries ? run(input.value) : unavailable();

    }

    function render() {

      results.innerHTML = matches.length
        ? matches.map((match, index) => result(match, index)).join('')
        : `<p class="search__empty">No results for &ldquo;${escape(query)}&rdquo;</p>`;

      open();

    }

    function unavailable() {

      matches = [];
      active = -1;

      results.innerHTML = '<p class="search__empty">Search is unavailable right now</p>';

      open();

    }

    function result(match, index) {

      var entry = match.entry;
      var chapter = entry.title == entry.chapter ? '' :
        `<span class="search__result-chapter">${escape(entry.chapter)}</span>`;

      return `
        <a class="search__result" href="${escape(entry.url)}" role="option" id="search-result-${index}" aria-selected="false" tabindex="-1">
          <span class="search__result-heading">
            <span class="search__result-title">${highlight(entry.title, match.pattern)}</span>
            ${chapter}
          </span>
          <span class="search__result-preview">${preview(entry.text, match.pattern)}</span>
        </a>
      `;

    }

    function navigate(e) {

      if(e.key == 'ArrowDown' || e.key == 'ArrowUp') {

        e.preventDefault();

        if(results.hidden) run(input.value);
        else select(active + (e.key == 'ArrowDown' ? 1 : -1));

      } else if(e.key == 'Enter' && !results.hidden) {

        var chosen = active >= 0 ? matches[active] : matches[0];

        if(chosen) {

          e.preventDefault();
          window.location = chosen.entry.url;

        }

      } else if(e.key == 'Tab') {

        // The results are a scroller, which Chrome will otherwise tab into
        close();

      } else if(e.key == 'Escape') {

        // A search input clears itself on Escape, which would take the query along
        // with the results — the second press does the clearing here instead
        e.preventDefault();

        if(results.hidden) {

          input.value = '';
          input.blur();

        } else {

          close();

        }

      }

    }

    function select(index) {

      var options = results.querySelectorAll('.search__result');

      if(!options.length) return;

      if(index < 0) index = options.length - 1;
      if(index >= options.length) index = 0;

      options.forEach(option => {

        option.classList.remove('search__result--active');
        option.setAttribute('aria-selected', 'false');

      });

      active = index;

      options[active].classList.add('search__result--active');
      options[active].setAttribute('aria-selected', 'true');
      options[active].scrollIntoView({ block: 'nearest' });

      input.setAttribute('aria-activedescendant', options[active].id);

    }

    function open() {

      results.hidden = false;

      input.setAttribute('aria-expanded', 'true');
      input.removeAttribute('aria-activedescendant');

    }

    function close() {

      results.hidden = true;
      matches = [];
      active = -1;

      input.setAttribute('aria-expanded', 'false');
      input.removeAttribute('aria-activedescendant');

    }

  }

}

function shortcut(e) {

  if(e.metaKey || e.ctrlKey || e.altKey) return false;
  if(e.target.closest('input, textarea, select, [contenteditable]')) return false;

  return e.key == '/';

}

// A load that fails isn't kept, so the next keystroke or focus tries again
function load() {

  loading ||= fetch(INDEX_URL)
    .then(response => response.ok ? response.json() : Promise.reject(response.status))
    .then(index => { entries = index; })
    .catch(() => { loading = null; });

  return loading;

}


/* Matching */

function lookup(entries, query) {

  var pattern = compile(query);

  if(!pattern) return [];

  return entries
    .map(entry => ({ entry: entry, pattern: pattern, score: score(entry, pattern) }))
    .filter(match => match.score > 0)
    .sort((a, b) => b.score - a.score || a.entry.url.localeCompare(b.entry.url));

}

// The same handful of expressions runs against every entry in the index, so a query
// is compiled once here rather than once per entry.
function compile(query) {

  var sources = tokenize(query).map(quote);

  if(!sources.length) return null;

  return {
    terms: sources.map(source => ({
      anywhere: matcher(source, 'giu'),
      whole: matcher(`${source}(?![\\p{L}\\p{N}])`, 'iu')
    })),
    phrase: query.toLowerCase(),
    first: matcher(`(?:${sources.join('|')})`, 'iu'),
    words: matcher(`(${sources.map(source => `${source}[\\p{L}\\p{N}]*`).join('|')})`, 'giu')
  };

}

function tokenize(query) {

  return query.toLowerCase().split(/[^\p{L}\p{N}+#_-]+/u).filter(Boolean);

}

// Every term has to appear in the section itself — a term that only shows up in the
// chapter title would otherwise drag in every other section of that chapter. Headings
// count for much more than body text, and the terms found as a run count for more
// than the same terms scattered across the section.
function score(entry, pattern) {

  var total = 0;

  for(const term of pattern.terms) {

    var inTitle = occurrences(entry.title, term.anywhere);
    var inText = occurrences(entry.text, term.anywhere);

    if(!inTitle && !inText) return 0;

    total += inTitle * 30 + Math.min(inText, 5) * 2 + occurrences(entry.chapter, term.anywhere) * 10;

    if(term.whole.test(entry.title)) total += 20;

  }

  if(pattern.terms.length > 1 && phrased(entry, pattern.phrase)) total += 40;

  return total;

}

function occurrences(text, term) {

  return (text.match(term) || []).length;

}

// Only entries that already matched every term get this far, so the text they are
// joined from is built here rather than carried on every entry in the index
function phrased(entry, phrase) {

  return `${entry.title} ${entry.chapter} ${entry.text}`.toLowerCase().includes(phrase);

}

// Terms match at the start of a word, so "nav" finds "navigation" but not "trackpad"
function matcher(source, flags) {

  return new RegExp(`(?<![\\p{L}\\p{N}])${source}`, flags);

}

// Hyphens in the text are optional, so "wifi" finds "Wi-Fi" and "dualboot" finds "dual-boot"
function quote(term) {

  return [...term].map(character => character.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('-?');

}


/* Rendering */

// Centred on the first term to appear, so the preview shows why the section matched
function preview(text, pattern) {

  var at = text.search(pattern.first);
  var start = Math.max(0, at - PREVIEW_LENGTH / 3);
  var snippet = text.slice(start, start + PREVIEW_LENGTH);

  if(start > 0) snippet = `…${snippet.replace(/^\S*\s/, '')}`;
  if(start + PREVIEW_LENGTH < text.length) snippet = `${snippet.replace(/\s\S*$/, '')}…`;

  return highlight(snippet, pattern);

}

// Splitting on a capturing pattern lands the matches on the odd indexes, so the
// surrounding text can be escaped and the matches wrapped in one pass.
function highlight(text, pattern) {

  return text
    .split(pattern.words)
    .map((part, index) => index % 2 ? `<mark>${escape(part)}</mark>` : escape(part))
    .join('');

}

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' };

function escape(text) {

  return text.replace(/[&<>"]/g, character => ESCAPES[character]);

}

export { ready };

import { For, Show, createMemo, createSignal, onSettled } from 'solid-js';
import * as stylex from '@stylexjs/stylex';
import { btopStyles as styles } from './BtopMonitor.stylex';

export type DesktopTaskId = 'about' | 'btop' | 'dhh-video' | 'network-video' | 'terminal' | 'files';

type HomeTask = {
  id: DesktopTaskId;
  title: string;
  workspace: number;
  open: boolean;
  minimized: boolean;
};

type BrowserMemory = {
  usedJSHeapSize: number;
  totalJSHeapSize: number;
  jsHeapSizeLimit: number;
};

type BrowserConnection = EventTarget & {
  effectiveType?: string;
  downlink?: number;
  rtt?: number;
  saveData?: boolean;
};

type ConnectionSnapshot = {
  effectiveType?: string;
  downlink?: number;
  rtt?: number;
  saveData?: boolean;
};

type BtopMonitorProps = {
  tasks: HomeTask[];
  onOpen: (id: DesktopTaskId) => void;
};

const taskLabels: Record<DesktopTaskId, string> = {
  about: 'About',
  btop: 'btop',
  'dhh-video': 'DHH Demo',
  'network-video': 'NetworkChuck Demo',
  terminal: 'Terminal',
  files: 'Files',
};

const systemProcesses = [
  ['chromium', '/usr/lib/chromium/chromium'],
  ['WebContent', 'browser content process'],
  ['Compositor', 'WebGL compositor thread'],
  ['Renderer', 'Solid application renderer'],
  ['Network', 'browser network service'],
  ['GPU Process', 'WebGL graphics process'],
  ['Audio', 'browser audio service'],
  ['Worker', 'site search index worker'],
  ['Vite', 'development module server'],
  ['CSS', 'StyleX atomic stylesheet'],
  ['Timer', 'performance sampler'],
  ['Session', 'Omarchy desktop session'],
] as const;

const formatBytes = (bytes: number) => {
  const units = ['B', 'KB', 'MB', 'GB'];
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${value >= 100 || unit === 0 ? value.toFixed(0) : value.toFixed(1)} ${units[unit]}`;
};

const formatUptime = (seconds: number) => {
  const total = Math.max(0, Math.floor(seconds));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const remainingSeconds = total % 60;
  return [hours, minutes, remainingSeconds].map((value) => String(value).padStart(2, '0')).join(':');
};

export default function BtopMonitor(props: BtopMonitorProps) {
  const [paused, setPaused] = createSignal(false);
  const [lagHistory, setLagHistory] = createSignal<number[]>([]);
  const [memory, setMemory] = createSignal<BrowserMemory | null>(null);
  const [memoryChecked, setMemoryChecked] = createSignal(false);
  const [environmentReady, setEnvironmentReady] = createSignal(false);
  const [platform, setPlatform] = createSignal('Detecting');
  const [cores, setCores] = createSignal<number | null>(null);
  const [viewport, setViewport] = createSignal('Detecting');
  const [uptime, setUptime] = createSignal(0);
  const [online, setOnline] = createSignal<boolean | null>(null);
  const [connection, setConnection] = createSignal<ConnectionSnapshot | null>(null);

  const currentLag = createMemo(() => lagHistory().at(-1));
  const chartMax = createMemo(() => Math.max(16, ...lagHistory()));
  const memoryPercent = createMemo(() => {
    const current = memory();
    if (!current?.jsHeapSizeLimit) return 0;
    return Math.min(100, (current.usedJSHeapSize / current.jsHeapSizeLimit) * 100);
  });

  const taskState = (task: HomeTask) => {
    if (!task.open) return 'STOP';
    if (task.minimized) return `MIN  WS${task.workspace}`;
    return `RUN  WS${task.workspace}`;
  };

  const visibleCores = createMemo(() => Array.from(
    { length: Math.min(32, Math.max(8, cores() ?? 8)) },
    (_, index) => ({ index, load: Math.round(((currentLag() ?? 2) * 7 + index * 11) % 18) }),
  ));

  onSettled(() => {
    const navigatorWithDetails = navigator as Navigator & {
      connection?: BrowserConnection;
      userAgentData?: { platform?: string };
    };
    const performanceWithMemory = performance as Performance & { memory?: BrowserMemory };
    const browserConnection = navigatorWithDetails.connection ?? null;
    let lastSample = performance.now();

    const readEnvironment = () => {
      const measuredMemory = performanceWithMemory.memory;
      if (measuredMemory) {
        setMemory({
          usedJSHeapSize: measuredMemory.usedJSHeapSize,
          totalJSHeapSize: measuredMemory.totalJSHeapSize,
          jsHeapSizeLimit: measuredMemory.jsHeapSizeLimit,
        });
      }
      setMemoryChecked(true);
      setPlatform(navigatorWithDetails.userAgentData?.platform || navigator.platform || 'Not exposed');
      setCores(navigator.hardwareConcurrency || null);
      setViewport(`${window.innerWidth} × ${window.innerHeight}`);
      setUptime(performance.now() / 1000);
      setOnline(navigator.onLine);
      setConnection(browserConnection ? {
        effectiveType: browserConnection.effectiveType,
        downlink: browserConnection.downlink,
        rtt: browserConnection.rtt,
        saveData: browserConnection.saveData,
      } : null);
      setEnvironmentReady(true);
    };

    const sample = () => {
      if (paused() || document.hidden) {
        lastSample = performance.now();
        return;
      }
      const now = performance.now();
      const delay = Math.max(0, now - lastSample - 500);
      lastSample = now;
      setLagHistory((current) => [...current, delay].slice(-32));
      readEnvironment();
    };

    readEnvironment();
    const sampleTimer = window.setInterval(sample, 500);
    const onVisibilityChange = () => { lastSample = performance.now(); };
    document.addEventListener('visibilitychange', onVisibilityChange);
    window.addEventListener('resize', readEnvironment);
    window.addEventListener('online', readEnvironment);
    window.addEventListener('offline', readEnvironment);
    browserConnection?.addEventListener('change', readEnvironment);

    return () => {
      window.clearInterval(sampleTimer);
      document.removeEventListener('visibilitychange', onVisibilityChange);
      window.removeEventListener('resize', readEnvironment);
      window.removeEventListener('online', readEnvironment);
      window.removeEventListener('offline', readEnvironment);
      browserConnection?.removeEventListener('change', readEnvironment);
    };
  });

  return (
    <div {...stylex.attrs(styles.home)} aria-label="btop browser system monitor">
      <header {...stylex.attrs(styles.topbar)}>
        <strong><span {...stylex.attrs(styles.pink)}>1</span>cpu</strong>
        <span>menu</span><span>preset *</span>
        <time {...stylex.attrs(styles.clock)}>{new Date().toLocaleTimeString([], { hour12: false })}</time>
        <button {...stylex.attrs(styles.pauseButton, styles.focusRing)} type="button" aria-pressed={paused() ? 'true' : 'false'} onClick={() => setPaused((value) => !value)}>
          {paused() ? 'resume' : 'pause'}
        </button>
      </header>

      <div {...stylex.attrs(styles.grid)}>
        <section {...stylex.attrs(styles.panel, styles.cpuPanel)} aria-labelledby="cpu-title">
          <div {...stylex.attrs(styles.panelHeading)}><h2 {...stylex.attrs(styles.panelTitle)} id="cpu-title">Ryzen Browser CPU</h2><span>{cores() ?? 8} cores</span></div>
          <div {...stylex.attrs(styles.cpuBody)}>
            <Show when={lagHistory().length} fallback={<p {...stylex.attrs(styles.emptyState)}>sampling cpu history...</p>}>
              <div {...stylex.attrs(styles.chart)} aria-hidden="true"><For each={lagHistory()}>{(value, index) => <span {...stylex.attrs(styles.chartBar, index() === lagHistory().length - 1 && styles.chartBarCurrent)} style={{ height: `${Math.max(2, (value / chartMax()) * 100)}%` }} />}</For></div>
            </Show>
            <div {...stylex.attrs(styles.coreGrid)}><For each={visibleCores()}>{(core) => <div {...stylex.attrs(styles.coreRow)}><span>C{core.index}</span><span {...stylex.attrs(styles.coreMeter)}>{'·'.repeat(Math.max(2, Math.round(core.load / 2)))}</span><strong>{core.load}%</strong><em>{32 + core.index % 5}°</em></div>}</For></div>
          </div>
          <p {...stylex.attrs(styles.uptime)}>up {formatUptime(uptime())} <span>load avg: {((currentLag() ?? 0) / 10).toFixed(2)}</span></p>
        </section>

        <section {...stylex.attrs(styles.panel, styles.memoryPanel)} aria-labelledby="memory-title">
          <div {...stylex.attrs(styles.panelHeading)}><h2 {...stylex.attrs(styles.panelTitle)} id="memory-title">mem</h2><span>{memory() ? `${memoryPercent().toFixed(0)}%` : 'n/a'}</span></div>
          <Show when={memory()} fallback={<p {...stylex.attrs(styles.emptyState)}>heap data unavailable</p>}>{(current) => <><dl {...stylex.attrs(styles.stackList)}><div><dt>Total</dt><dd>{formatBytes(current().jsHeapSizeLimit)}</dd></div><div><dt>Used</dt><dd>{formatBytes(current().usedJSHeapSize)}</dd></div><div><dt>Free</dt><dd>{formatBytes(current().jsHeapSizeLimit - current().usedJSHeapSize)}</dd></div></dl><div {...stylex.attrs(styles.memoryMeter)} aria-hidden="true"><span style={{ height: `${Math.max(8, memoryPercent())}%`, width: '100%', 'background-color': '#76c7a0', opacity: 0.78 }} /></div><div {...stylex.attrs(styles.blockGraph)} aria-hidden="true">▁▁▂▂▃▃▄▄▅▅▆▇</div></>}</Show>
        </section>

        <section {...stylex.attrs(styles.panel, styles.diskPanel)} aria-labelledby="disk-title">
          <div {...stylex.attrs(styles.panelHeading)}><h2 {...stylex.attrs(styles.panelTitle)} id="disk-title">disks</h2><span>io</span></div>
          <dl {...stylex.attrs(styles.diskList)}><div><dt>root</dt><dd><span>Used 51%</span><b>▰▰▰▰▱▱▱▱</b></dd></div><div><dt>home</dt><dd><span>Used 51%</span><b>▰▰▰▰▱▱▱▱</b></dd></div><div><dt>boot</dt><dd><span>Used 41%</span><b>▰▰▰▱▱▱▱▱</b></dd></div></dl>
        </section>

        <section {...stylex.attrs(styles.panel, styles.networkPanel)} aria-labelledby="network-title">
          <div {...stylex.attrs(styles.panelHeading)}><h2 {...stylex.attrs(styles.panelTitle)} id="network-title">net</h2><span {...stylex.attrs(styles.networkState, online() === false && styles.networkOffline)}>{online() ? 'sync auto' : 'offline'}</span></div>
          <div {...stylex.attrs(styles.netGraph)} aria-hidden="true">▁▁▂▃▅▂▆▃▂▇▅▂▁</div>
          <dl {...stylex.attrs(styles.stackList)}><div><dt>download</dt><dd>{connection()?.downlink ? `${connection()!.downlink} Mbps` : 'not exposed'}</dd></div><div><dt>rtt</dt><dd>{connection()?.rtt ? `${connection()!.rtt} ms` : 'not exposed'}</dd></div></dl>
        </section>

        <section {...stylex.attrs(styles.panel, styles.processPanel)} aria-labelledby="process-title">
          <div {...stylex.attrs(styles.panelHeading)}><h2 {...stylex.attrs(styles.panelTitle)} id="process-title">proc</h2><span>filter　per-core　tree</span></div>
          <div {...stylex.attrs(styles.processHeader)}><span>Pid</span><span>Program</span><span>MemB</span><span>Cpu%</span></div>
          <div {...stylex.attrs(styles.processList)}>
            <For each={props.tasks}>{(task, index) => <button {...stylex.attrs(styles.processRow, index() === 0 && styles.processSelected, styles.focusRing)} type="button" onClick={() => props.onOpen(task.id)} aria-label={`${taskLabels[task.id]}: ${taskState(task)}. Activate app.`}><span>{4980 + index() * 317}</span><strong>{taskLabels[task.id]}</strong><span>{task.open ? 215 + index() * 39 : 0}M</span><span>{task.open ? (0.1 + index() * 0.1).toFixed(1) : '0.0'}</span></button>}</For>
            <For each={systemProcesses}>{(process, index) => <div {...stylex.attrs(styles.processStaticRow)}><span>{7934 + index() * 211}</span><span title={process[1]}>{process[0]}</span><span>{64 + index() * 23}M</span><span>{(index() % 4 / 10).toFixed(1)}</span></div>}</For>
          </div>
          <footer {...stylex.attrs(styles.processFooter)}>↑ select　↓ info　↵ open　q close <span>{props.tasks.filter((task) => task.open).length}/{props.tasks.length}</span></footer>
        </section>
      </div>
    </div>
  );
}

.security {
